// This script reads the passed in alexandria_core.json config and generates an HTML file with tables for the different categories.
// This code was generated by different AIs but checked against a real alexandria_core.json config
// ! Use at your own risk !

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const filePath = process.argv[2];
if (!filePath) {
  console.error("Usage: node script.js <path_to_json_file>");
  process.exit(1);
}

fs.readFile(path.resolve(__dirname, filePath), "utf8", (err, data) => {
  if (err) {
    console.error("Error reading file:", err);
    process.exit(1);
  }

  try {
    const jsonData = JSON.parse(data);
    const categories = {};

    jsonData.forEach((item) => {
      if (item.model === "alexandria_core.category") {
        categories[item.pk] = item;
      }
    });

    let htmlContent = `<!DOCTYPE html>
<html>
<head>
  <title>Permissions Table</title>
  <style>
    table { width: 100%; border-collapse: collapse; margin-bottom: 20px; }
    th, td { border: 1px solid black; padding: 8px; text-align: left; }
    th { background-color: #f2f2f2; }
    .fields-cell { font-size: 0.9em; color: #666; }
    .scope-cell { font-style: italic; color: #444; }
    .category-header {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-bottom: 10px;
    }
    .color-box {
      width: 20px;
      height: 20px;
      border: 1px solid #999;
      display: inline-block;
    }
  </style>
</head>
<body>
  <h1>Permissions Overview</h1>
`;

    Object.values(categories).forEach((item) => {
      const categoryName = JSON.parse(item.fields.name).de || "Unknown";
      const parentCategory = item.fields.parent
        ? categories[item.fields.parent]?.fields.name
          ? JSON.parse(categories[item.fields.parent].fields.name).de
          : "Unknown Parent"
        : "None";
      const access = item.fields.metainfo?.access || {};
      const color = item.fields.color || "#CCCCCC";

      htmlContent += `
      <div class="category-header">
        <div class="color-box" style="background-color: ${color}"></div>
        <h2 style="margin: 0">${categoryName} (Parent: ${parentCategory})</h2>
      </div>
      <table>
        <tr>
          <th>Role</th>
          <th>Visibility</th>
          <th>Permission</th>
          <th>Scope</th>
          <th>Fields</th>
          <th>Condition</th>
        </tr>
      `;

      Object.entries(access).forEach(([role, details]) => {
        const visibility = details.visibility || "N/A";
        const permissions = details.permissions || [];
        const rowspan = Math.max(1, permissions.length);

        htmlContent += `<tr>
          <td rowspan="${rowspan}">${role}</td>
          <td rowspan="${rowspan}">${visibility}</td>
        `;

        if (permissions.length === 0) {
          htmlContent += `<td>None</td>
            <td>-</td>
            <td>All</td>
            <td>Always</td>
          </tr>`;
        } else {
          permissions.forEach((p, index) => {
            const condition = p.condition
              ? JSON.stringify(p.condition)
              : "Always";
            const fields = p.fields
              ? Array.isArray(p.fields)
                ? p.fields.join(", ")
                : p.fields
              : "All";
            const scope = p.scope || "-";

            if (index === 0) {
              htmlContent += `<td>${p.permission}</td>
                <td class="scope-cell">${scope}</td>
                <td class="fields-cell">${fields}</td>
                <td>${condition}</td>
              </tr>`;
            } else {
              htmlContent += `<tr>
                <td>${p.permission}</td>
                <td class="scope-cell">${scope}</td>
                <td class="fields-cell">${fields}</td>
                <td>${condition}</td>
              </tr>`;
            }
          });
        }
      });

      htmlContent += `</table>`;
    });

    htmlContent += `</body></html>`;

    fs.writeFile(
      path.resolve(__dirname, "permissions.html"),
      htmlContent,
      "utf8",
      (err) => {
        if (err) {
          console.error("Error writing HTML file:", err);
          process.exit(1);
        }
        console.log("permissions.html has been generated successfully.");
      },
    );
  } catch (parseError) {
    console.error("Error parsing JSON:", parseError);
    process.exit(1);
  }
});
